def minPath(grid, k):
    n = len(grid)
    if k == 1:
        min_val = min(min(row) for row in grid)
        return [min_val]

    pos = {}
    for i in range(n):
        for j in range(n):
            pos[grid[i][j]] = (i, j)

    start_val = min(pos.keys())
    start_pos = pos[start_val]

    from collections import defaultdict
    best = defaultdict(list)
    best[(start_pos[0], start_pos[1])] = [start_val]

    from heapq import heappush, heappop
    heap = []
    heappush(heap, ([start_val], start_pos[0], start_pos[1]))

    dirs = [(-1,0),(1,0),(0,-1),(0,1)]

    for step in range(1, k):
        new_best = defaultdict(list)
        new_heap = []
        seen = set()
        while heap:
            path, x, y = heappop(heap)
            if (x, y) in seen:
                continue
            seen.add((x, y))
            for dx, dy in dirs:
                nx, ny = x + dx, y + dy
                if 0 <= nx < n and 0 <= ny < n:
                    new_path = path + [grid[nx][ny]]
                    key = (nx, ny)
                    if key not in new_best or new_path < new_best[key]:
                        new_best[key] = new_path
                        heappush(new_heap, (new_path, nx, ny))
        heap = new_heap
        best = new_best

    result = None
    for path in best.values():
        if result is None or path < result:
            result = path
    return result

