    n = len(grid)
    if k == 1:
        return [min(min(row) for row in grid)]

    # BFS-like approach: for each step, keep the best path ending at each cell
    # Initialize with step 1: each cell's path is just its value
    best = {}
    for i in range(n):
        for j in range(n):
            best[(i, j)] = [grid[i][j]]

    for step in range(2, k + 1):
        new_best = {}
        for (i, j), path in best.items():
            for di, dj in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                ni, nj = i + di, j + dj
                if 0 <= ni < n and 0 <= nj < n:
                    new_path = path + [grid[ni][nj]]
                    key = (ni, nj)
                    if key not in new_best or new_path < new_best[key]:
                        new_best[key] = new_path
        best = new_best

    # Find the global minimum path
    result = None
    for path in best.values():
        if result is None or path < result:
            result = path
    return result

